query:
CREATE TABLE IF NOT EXISTS `clickAnalytics` (
	`id` int AUTO_INCREMENT NOT NULL,
	`productId` int NOT NULL,
	`userId` varchar(64),
	`action` varchar(64) NOT NULL,
	`timestamp` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `clickAnalytics_id` PRIMARY KEY(`id`)
);
CREATE TABLE IF NOT EXISTS `embedVariants` (
	`id` int AUTO_INCREMENT NOT NULL,
	`testId` varchar(255) NOT NULL,
	`variantName` varchar(255) NOT NULL,
	`embedData` json NOT NULL,
	`clicks` int NOT NULL DEFAULT 0,
	`conversions` int NOT NULL DEFAULT 0,
	`status` enum('active','inactive') NOT NULL DEFAULT 'active',
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `embedVariants_id` PRIMARY KEY(`id`)
);
ALTER TABLE `orders` ADD COLUMN IF NOT EXISTS `deliveryStatus` enum('pending','sent','failed') DEFAULT 'pending' NOT NULL;
ALTER TABLE `orders` ADD COLUMN IF NOT EXISTS `deliveryAttempts` int DEFAULT 0 NOT NULL;
ALTER TABLE `orders` ADD COLUMN IF NOT EXISTS `lastDeliveryAttempt` timestamp;
ALTER TABLE `products` ADD COLUMN IF NOT EXISTS `assetKey` varchar(255);
ALTER TABLE `products` ADD COLUMN IF NOT EXISTS `isDigital` boolean DEFAULT false NOT NULL;
ALTER TABLE `clickAnalytics` ADD CONSTRAINT IF NOT EXISTS `clickAnalytics_productId_products_id_fk` FOREIGN KEY (`productId`) REFERENCES `products`(`id`) ON DELETE no action ON UPDATE no action;
CREATE INDEX IF NOT EXISTS `clickAnalytics_productId_idx` ON `clickAnalytics` (`productId`);
CREATE INDEX IF NOT EXISTS `clickAnalytics_userId_idx` ON `clickAnalytics` (`userId`);
CREATE INDEX IF NOT EXISTS `embedVariants_testId_idx` ON `embedVariants` (`testId`);
CREATE INDEX IF NOT EXISTS `orders_deliveryStatus_idx` ON `orders` (`deliveryStatus`);

